            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            top = min(rr for rr, cc in comp)
            bottom = max(rr for rr, cc in comp)
            left = min(cc for rr, cc in comp)
            right = max(cc for rr, cc in comp)
            if bottom-top < 2 or right-left < 2:
                continue
            # A single missing cell in the top edge is the mouth of the enclosure.
            gaps = [cc for cc in range(left+1, right) if grid[top][cc] != 5]
            if len(gaps) != 1:
                continue
            mouth = gaps[0]
            if grid[bottom][left:right+1] != [5] * (right-left+1):
                continue
            # Fill the enclosed interior, then extend the escaping mark leftward above it.
            for rr in range(top+1, bottom):
                for cc in range(left+1, right):
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 2
            if top > 0:
                for cc in range(mouth, -1, -1):
                    out[top-1][cc] = 2
    return out
